const KEY='lamma-v1',spots=[['شارع التسعين',30.020,31.425],['محيط الجامعة الأمريكية',30.018,31.500],['التجمع الأول',30.060,31.440],['الرحاب',30.060,31.490]];
const seed=()=>({orders:[{id:1,name:'مكتبة الحي',spot:0,weight:12,time:'صباحًا',status:'new'},{id:2,name:'ماركت النور',spot:0,weight:18,time:'صباحًا',status:'new'},{id:3,name:'محل البيت',spot:2,weight:9,time:'مساءً',status:'new'},{id:4,name:'ورق وقلم',spot:1,weight:22,time:'صباحًا',status:'new'}],route:[]});
let state;try{state=JSON.parse(localStorage.getItem(KEY))||seed()}catch{state=seed()}let tab='shop',proposal=[];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('تعذر الحفظ في المتصفح؛ اترك الصفحة مفتوحة.')}};
function toast(s){let t=document.querySelector('#toast');t.textContent=s;t.style.display='block';setTimeout(()=>t.style.display='none',3200)}
const options=()=>spots.map((s,i)=>`<option value="${i}">${s[0]}</option>`).join('');
const statuses={new:'متاح',booked:'في جولة',done:'تم الاستلام',cancelled:'ملغي'};
function card(o){return `<article class="card"><div class="cardhead"><h3>${esc(o.name)}</h3><span class="badge">${statuses[o.status]}</span></div><p>${spots[o.spot][0]} · ${o.time}</p><div class="cardhead"><span class="weight">${o.status==='done'?o.actual:o.weight} <small>كجم ${o.status==='done'?'فعلي':'تقريبي'}</small></span>${tab==='shop'&&o.status==='new'?`<button class="ghost" onclick="cancelOrder(${o.id})">إلغاء الطلب</button>`:''}${tab==='collector'&&o.status==='booked'?`<button onclick="completeForm(${o.id})">تسجيل الاستلام</button>`:''}</div>${o.status==='done'?`<p>سعر الكيلو: ${o.price} ج.م · الإجمالي: ${(o.actual*o.price).toFixed(2)} ج.م</p>`:''}</article>`}
function render(){document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));let c=document.querySelector('#content');if(tab==='shop'){c.innerHTML=`<div class="grid"><form class="panel" id="add"><h3>الكرتون جاهز؟</h3><p class="small">أضف طلبًا للنسخة التجريبية. المواقع مناطق تقريبية ثابتة وليست عناوين استلام حقيقية.</p><label>اسم المحل</label><input name="name" required maxlength="60" placeholder="مثال: مكتبة الحي"><label>منطقة الاستلام</label><select name="spot">${options()}</select><div class="row"><div><label>الوزن التقريبي / كجم</label><input name="weight" type="number" min="1" max="1000" required placeholder="15"></div><div><label>الموعد</label><select name="time"><option>صباحًا</option><option>مساءً</option></select></div></div><button class="full">إضافة طلب +</button></form><div class="cards"><h3>طلبات المحلات <span class="small">/ عرض تجريبي مشترك</span></h3>${state.orders.slice().reverse().map(card).join('')||'<div class="empty">لا توجد طلبات بعد.</div>'}</div></div>`;document.querySelector('#add').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);const name=d.get('name').trim();if(!name)return;state.orders.push({id:Date.now(),name,spot:+d.get('spot'),weight:+d.get('weight'),time:d.get('time'),status:'new'});save();render();toast('تمت إضافة الطلب. انتقل لواجهة الجامع لتجربته.')}}else if(tab==='collector'){const active=state.orders.filter(o=>o.status==='booked');c.innerHTML=`<div class="grid"><form class="panel" id="plan"><h3>جهّز مشوارك</h3><label>نقطة البداية التقريبية</label><select name="start">${options()}</select><label>سعة النقل / كجم</label><input type="number" name="capacity" min="1" max="5000" value="50" required><label>موعد الجولة</label><select name="time"><option>صباحًا</option><option>مساءً</option></select><button class="full" ${active.length?'disabled':''}>اقترح جولة ←</button><p class="small">اختيار حسب القرب والوزن والموعد. المسافة خط مستقيم بين مراكز المناطق، وليست مسافة قيادة. أكمل الجولة الحالية أو حررها قبل اقتراح أخرى.</p>${active.length?'<button type="button" class="ghost full" onclick="releaseRoute()">تحرير الطلبات المتبقية</button>':''}</form><div class="cards"><div id="proposal"></div><h3>${active.length?'جولتك الحالية':'الطلبات المتاحة'}</h3>${(active.length?state.route.map(id=>state.orders.find(o=>o.id===id)).filter(o=>o&&o.status==='booked'):state.orders.filter(o=>o.status==='new')).map(card).join('')||'<div class="empty">لا توجد طلبات متاحة. أضف طلبًا من واجهة المحل.</div>'}</div></div>`;document.querySelector('#plan').onsubmit=e=>{e.preventDefault();let d=new FormData(e.target),remaining=+d.get('capacity'),start=+d.get('start'),pos=start,total=0;let available=state.orders.filter(o=>o.status==='new'&&o.time===d.get('time'));proposal=[];while(available.length){available.sort((a,b)=>distance(pos,a.spot)-distance(pos,b.spot));const next=available.find(o=>o.weight<=remaining);if(!next)break;total+=distance(pos,next.spot);pos=next.spot;proposal.push(next.id);remaining-=next.weight;available=available.filter(o=>o.id!==next.id)}document.querySelector('#proposal').innerHTML=proposal.length?`<div class="route"><h3>اقتراح مناسب لمشوارك</h3><p>${proposal.length} وقفات · ${(+d.get('capacity')-remaining)} كجم · ${total.toFixed(1)} كم تقريبية</p><ol>${proposal.map(id=>{const o=state.orders.find(x=>x.id===id);return `<li>${esc(o.name)} — ${spots[o.spot][0]}</li>`}).join('')}</ol><p class="small">لا تشمل المسافة العودة. مواقع توضيحية، وليست ملاحة حقيقية.</p><button onclick="acceptRoute()">اعتماد الجولة</button></div>`:'<div class="empty">لا توجد طلبات تناسب الموعد والسعة. جرّب زيادة السعة أو تغيير الموعد.</div>'}}else{const done=state.orders.filter(o=>o.status==='done'),weight=done.reduce((a,o)=>a+o.actual,0),value=done.reduce((a,o)=>a+o.actual*o.price,0);c.innerHTML=`<div class="stats"><div class="stat">كرتون تم استلامه<strong>${weight.toFixed(1)}</strong><span>كيلوجرام مسجل فعليًا</span></div><div class="stat">طلبات مكتملة<strong>${done.length}</strong><span>عملية استلام موثقة داخل التجربة</span></div><div class="stat">قيمة المعاملات<strong>${value.toFixed(2)}</strong><span>جنيه مصري · ليست أرباح المنصة</span></div></div><div class="panel" style="margin-top:20px"><h3>من التقدير للحقيقة</h3><p class="small">الوزن المتوقع للطلبات المكتملة: ${done.reduce((a,o)=>a+o.weight,0)} كجم. الوزن الفعلي: ${weight.toFixed(1)} كجم. الأرقام ناتجة عن إدخالاتك التجريبية، ولا تثبت التدوير أو أي وفر بيئي.</p></div>`}}
function distance(a,b){const x=spots[a],y=spots[b];return Math.hypot((x[1]-y[1])*111,(x[2]-y[2])*96)}
function cancelOrder(id){let o=state.orders.find(o=>o.id===id);if(o.status!=='new')return;o.status='cancelled';save();render()}
function acceptRoute(){if(!proposal.length||proposal.some(id=>state.orders.find(o=>o.id===id)?.status!=='new'))return;state.route=[...proposal];proposal.forEach(id=>state.orders.find(o=>o.id===id).status='booked');proposal=[];save();render();toast('الجولة جاهزة. سجّل الاستلام عند كل وقفة.')}
function releaseRoute(){state.orders.forEach(o=>{if(o.status==='booked')o.status='new'});state.route=[];save();render()}
function completeForm(id){const o=state.orders.find(o=>o.id===id),dialog=document.querySelector('#dialog');dialog.innerHTML=`<form id="finish"><h2>تأكيد استلام الكرتون</h2><p>${esc(o.name)}</p><label>الوزن الفعلي المستلم / كجم</label><input name="actual" type="number" min="0.1" max="5000" step="0.1" value="${o.weight}" required><label>سعر الكيلو المتفق عليه / جنيه</label><input name="price" type="number" min="0" max="10000" step="0.01" required placeholder="أدخل السعر المتفق عليه"><p class="small">تسجيل فقط؛ لا يتم تحويل أموال. إذا استلمت جزءًا، يُغلق هذا الطلب بالوزن المسجل ويمكن إضافة طلب جديد للباقي.</p><div class="row"><button>تأكيد الاستلام</button><button type="button" class="ghost" onclick="document.querySelector('#dialog').close()">رجوع</button></div></form>`;dialog.showModal();document.querySelector('#finish').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);o.actual=+d.get('actual');o.price=+d.get('price');o.status='done';save();dialog.close();render();toast('تم تسجيل الاستلام وتحديث النتائج.')}}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;proposal=[];render()});document.querySelector('#reset').onclick=()=>{if(confirm('إعادة البيانات التجريبية وحذف تغييرات هذا المتصفح؟')){state=seed();save();render()}};render();
